            5 => [null, null, 'Cuốn sách hướng người đọc quay vào bên trong để hiểu rõ chính mình trước những biến động của cuộc sống. Khi thấu suốt nội tâm, ta sẽ đứng vững và giữ được sự bình tĩnh giữa những lúc khó khăn.'],
            6 => [176, '19 x 13 x 1.2 cm', 'Cuốn đầu tiên trong bộ ba sách về xây dựng thương hiệu của Leader Thanh, tập trung vào việc đặt tên. Sách phân tích vì sao một cái tên tốt giúp thương hiệu dễ nhớ, dễ lan tỏa và đưa ra nguyên tắc để tự đặt tên cho sản phẩm, doanh nghiệp.'],
            7 => [null, null, 'Cuốn sách bàn về trải nghiệm khách hàng như một lợi thế cạnh tranh của doanh nghiệp. Nội dung đi từ việc lựa chọn trải nghiệm muốn mang lại, thiết kế các điểm chạm đến cách duy trì và nuôi dưỡng trải nghiệm đó lâu dài.'],
            8 => [260, null, 'Trần Quang Sang chia sẻ kinh nghiệm khởi nghiệp và vận hành quán ăn bán qua các ứng dụng giao đồ ăn. Người đọc được hướng dẫn cách chuẩn bị, xây dựng gian hàng và những "công thức" giúp bán hàng hiệu quả trên các nền tảng này.'],
            9 => [null, null, 'Russ Laraway viết cho những người vừa trở thành quản lý: kỹ năng giúp một người làm giỏi việc cá nhân chưa chắc giúp họ dẫn dắt đội nhóm. Sách đưa ra cách quản lý con người bằng sự quan tâm thật lòng và tầm nhìn rõ ràng để giữ chân nhân viên.'],
            10 => [null, null, 'Cuốn sách bàn về những thay đổi của công tác quản lý nhân sự khi công nghệ và dữ liệu len vào mọi khâu, từ tuyển dụng, đào tạo đến đánh giá. Người đọc được gợi ý cách kết hợp công cụ số với yếu tố con người để xây dựng đội ngũ hiệu quả.'],
            11 => [null, '20.5 x 14.5 x 1.6 cm', 'Một cuốn sách nhẹ nhàng, khích lệ người đọc nhìn cuộc sống bằng thái độ tích cực. Dù ngẩng lên hay cúi xuống, ở đâu cũng có điều đẹp đẽ nếu ta biết trân trọng những điều nhỏ bé quanh mình.'],
            12 => [null, null, 'Tác phẩm của Jeong JiA ghi lại những suy nghĩ, tình cảm của một người cha dành cho con. Những trang viết giản dị giúp người đọc hiểu hơn về tình cha thầm lặng và những điều cha mẹ thường không nói thành lời.'],
