            16 => [72, '27.5 x 20.5 x 0.5 cm', 'Sách bài tập đi kèm sách giáo khoa Tiếng Anh 7 Friends Plus. Các bài luyện từ vựng, ngữ pháp, đọc và viết được sắp xếp theo từng bài học, giúp học sinh ôn tập và củng cố kiến thức trên lớp.'],
            17 => [148, '26.5 x 19 cm', 'Tài liệu luyện kỹ năng đọc hiểu tiếng Anh dành cho học sinh lớp 6 của tác giả Khánh Hà. Sách gồm nhiều bài đọc theo chủ đề quen thuộc kèm câu hỏi, giúp các em mở rộng vốn từ và làm quen với các dạng bài đọc hiểu.'],
            18 => [260, '24 x 16 x 1.3 cm', 'Sách luyện nghe IELTS bằng phương pháp nghe chép chính tả. Người học nghe từng đoạn hội thoại, bài nói và ghi lại chính xác, qua đó rèn khả năng bắt từ và tăng độ chính xác khi làm bài thi Listening.'],
            19 => [608, '27 x 19 x 2.8 cm', 'Cuốn tổng ôn ngữ pháp tiếng Anh của cô Trang Anh dành cho học sinh ôn thi tốt nghiệp THPT. Kiến thức được hệ thống theo chuyên đề, kèm nhiều bài tập vận dụng và mẹo làm bài.'],
            20 => [295, '27 x 19 x 1.4 cm', 'Tuyển tập 100 đề minh họa môn Ngữ Văn theo định hướng kỳ thi tốt nghiệp THPT từ năm 2025. Các đề đều có hướng dẫn giải chi tiết để học sinh tự luyện và đánh giá năng lực.'],
            21 => [32, '24 x 17 x 0.2 cm', 'Sách hướng dẫn bé gấp giấy origami thành các con vật ngộ nghĩnh trong vườn thú. Các bước gấp được minh họa rõ ràng, giúp trẻ rèn sự khéo léo, tập trung và óc sáng tạo.'],
            22 => [96, '20.5 x 14.5 cm', 'Sách kỹ năng giúp học sinh tiểu học nhận biết và quản lý cảm xúc của mình. Các tình huống gần gũi kèm bài tự rèn luyện giúp trẻ bình tĩnh, tự tin hơn khi gặp thử thách.'],
            23 => [48, '18 x 18 x 0.2 cm', 'Sách tô màu với 20 bức tranh về các lễ hội đặc sắc trên thế giới, kèm một tờ sticker. Bé vừa tô màu vừa khám phá văn hóa, phong tục của nhiều quốc gia.'],
            24 => [null, '29.5 x 20.8 cm', 'Sách tranh của Dagmar Geisler giúp trẻ hiểu vì sao không được đi theo người lạ, dù người đó tỏ ra thân thiện. Qua câu chuyện gần gũi, cha mẹ và con cùng xây dựng những quy tắc an toàn để tự bảo vệ mình.'],
            25 => [null, null, 'Cuốn sách thuộc bộ "10 vạn câu hỏi vì sao", giải đáp những thắc mắc về thiên nhiên và các hiện tượng kỳ bí quanh ta. Kiến thức khoa học được trình bày ngắn gọn, dễ hiểu, phù hợp với trí tò mò của các bạn nhỏ.'],
            26 => [120, null, 'Sách của The School of Life dành cho những ai muốn yêu và được yêu một cách chân thành. Cuốn sách giúp người đọc hiểu mình trước khi tìm hiểu người khác, từ đó biết chọn lựa, thấu hiểu và giữ gìn một tình yêu trưởng thành.'],
            27 => [null, '20 x 12 cm', 'Tập truyện ngắn và tản văn của Jun Phạm về tình yêu, tuổi trẻ và những giấc mơ dang dở. Giọng văn nhẹ nhàng, nhiều hoài niệm, dễ khiến người đọc nhớ về những người, những chuyện đã đi qua.'],
            28 => [192, null, 'Cuốn sách mang tinh thần chánh niệm, nhắc người đọc rằng mọi thứ trong đời đều vô thường. Khi biết sống tỉnh thức với hiện tại, ta có thể tìm thấy sự bình an ngay giữa những đổi thay.'],
            29 => [208, '17 x 12 x 1 cm', 'Sách song ngữ Việt - Trung của Nguyên Trần, mỗi ngày một trang với những câu manifest tích cực trong suốt 365 ngày. Người đọc vừa nuôi dưỡng suy nghĩ tích cực, vừa có thể luyện thêm tiếng Trung.'],
            30 => [null, null, 'Tiểu thuyết của nhà văn Tô Hoài lấy bối cảnh vùng ven Hà Nội xưa. Câu chuyện về những tay anh chị, kẻ cướp nơi bến Bỏi tái hiện đời sống, phong tục và con người Hà Nội đầu thế kỷ XX.'],
            31 => [305, '28.5 x 21 x 1.5 cm', 'Giáo trình ngữ pháp và từ vựng tiếng Anh trình độ C1 - C2 của Malcolm Mann, có kèm đáp án. Sách xen kẽ các bài ngữ pháp và từ vựng theo chủ đề, phù hợp ôn luyện các kỳ thi tiếng Anh nâng cao.'],
            32 => [null, null, 'Cuốn sách của Mai Lan Hương giải thích các điểm ngữ pháp tiếng Anh một cách hệ thống, dễ hiểu. Mỗi chủ điểm đều có ví dụ minh họa và bài tập kèm đáp án để người học tự luyện tập.'],
            33 => [141, '28.5 x 21 x 1 cm', 'Giáo trình chuẩn HSK 1 dành cho người mới bắt đầu học tiếng Trung, bám sát nội dung kỳ thi HSK cấp 1. Sách gồm các bài học về phát âm, từ vựng và mẫu câu giao tiếp cơ bản.'],
            34 => [null, null, 'Giáo trình luyện nói tiếng Trung cấp tốc dành cho người mới bắt đầu của tác giả Mã Tiễn Phi. Các bài học xoay quanh tình huống giao tiếp hằng ngày, giúp người học nhanh chóng nói được những câu cơ bản.'],
            35 => [250, '27 x 19 x 1.1 cm', 'Sách bài tập đi kèm giáo trình Tiếng Hàn tổng hợp dành cho người Việt Nam, trình độ sơ cấp 1. Các bài luyện từ vựng, ngữ pháp, nghe, đọc, viết bám theo từng bài trong sách giáo trình.'],
            36 => [462, '24 x 17 cm', 'Sách ngữ pháp tiếng Hàn trình độ trung cấp, giải thích các cấu trúc thường dùng bằng tiếng Việt kèm ví dụ và bài tập. Phù hợp cho người đã học xong sơ cấp và đang ôn luyện kỳ thi TOPIK.'],
            37 => [400, '20.5 x 14 x 2 cm', 'Hồi ký của Thiếu tướng Hoàng Đan về chặng đường chiến đấu từ bờ sông Bến Hải đến ngày giải phóng miền Nam. Sách ghi lại nhiều trận đánh và bài học chỉ huy từ góc nhìn của một vị tướng trực tiếp tham chiến.'],
            38 => [232, '24 x 16 cm', 'Tác giả Nguyễn Văn Tàu kể lại những câu chuyện về hoạt động tình báo trong thời kỳ kháng chiến. Những chuyện có thật, nhiều hiểm nguy và mưu trí được thuật lại sinh động, giúp người đọc hiểu thêm về mặt trận thầm lặng.'],
            39 => [278, '19 x 12 cm', 'Dũng Phan kể lại 12 giai đoạn, sự kiện tiêu biểu trong lịch sử Việt Nam bằng giọng văn hào hùng như những khúc tráng ca. Lịch sử được viết gần gũi, dễ đọc, khơi gợi niềm tự hào dân tộc ở người trẻ.'],
            40 => [244, '20.5 x 15 x 1.1 cm', 'Sách giới thiệu những nguyên tắc nuôi dạy con của người Do Thái, chú trọng tư duy độc lập, tinh thần tự lập và lòng tự tin. Cha mẹ có thể áp dụng các gợi ý trong sách vào việc dạy con hằng ngày.'],
            41 => [null, null, 'Cuốn sách trong bộ "Giúp con hạnh phúc" với 35 hoạt động vui chơi dành cho trẻ từ 3 đến 10 tuổi. Qua các trò chơi, cha mẹ giúp con nhận biết, gọi tên và điều hòa cảm xúc của mình.'],
            42 => [null, null, 'Sách hướng dẫn cha mẹ xây dựng chế độ ăn hợp lý cho trẻ theo từng giai đoạn phát triển. Nội dung gồm kiến thức dinh dưỡng cơ bản và cách chăm sóc bữa ăn để trẻ khỏe mạnh.'],
            43 => [200, '23 x 15.5 cm', 'Cuốn sách của bác sĩ Trần Thị Huyên Thảo giúp cha mẹ chăm sóc sức khỏe cho trẻ nhỏ. Sách giải đáp những thắc mắc thường gặp về bệnh vặt, dinh dưỡng và sự phát triển của trẻ bằng ngôn ngữ dễ hiểu.'],
            44 => [256, '23 x 17 cm', 'Sách thai giáo của chuyên gia Trạch Quế Vinh, đồng hành cùng mẹ bầu suốt 280 ngày mang thai. Mỗi ngày một trang với kiến thức, hoạt động và lời khuyên giúp mẹ khỏe mạnh và kết nối với em bé.'],
            45 => [237, '20.5 x 14.5 x 1.1 cm', 'Cẩm nang hướng dẫn chăm sóc sản phụ sau sinh và trẻ sơ sinh trong những tháng đầu đời. Sách cung cấp kiến thức về dinh dưỡng, phục hồi sức khỏe cho mẹ và cách chăm sóc, theo dõi sự phát triển của bé.'],
            46 => [184, '17.6 x 11.3 cm', 'Tập 106 của bộ manga trinh thám nổi tiếng của Gosho Aoyama. Conan tiếp tục cùng các nhân vật quen thuộc phá giải những vụ án mới đầy bất ngờ.'],
            47 => [192, '17.6 x 11.3 x 0.9 cm', 'Truyện tranh của Fujiko F. Fujio, tác giả Doraemon, kể về cậu bé Mitsuo được trao bộ đồ giúp trở thành siêu nhân Perman. Tập 4 tiếp tục những chuyến phiêu lưu hài hước khi Mitsuo vừa đi học vừa làm nhiệm vụ giúp đỡ mọi người.'],
            48 => [178, '18 x 13 x 0.8 cm', 'Tập 23 của bộ manga kỳ bí "Cậu" ma nhà xí Hanako của AidaIro. Câu chuyện về Nene và Hanako tiếp tục với những bí ẩn mới trong ngôi trường đầy truyền thuyết; bản phát hành kèm postcard phong thư.'],
            49 => [null, null, 'Tập 11 của bộ truyện tranh tình cảm "Tình yêu nhân vật phụ". Câu chuyện xoay quanh những nhân vật tưởng chỉ đứng bên lề nhưng cũng có những rung động và chuyện tình của riêng mình.'],
            50 => [196, '17.6 x 11.3 x 0.9 cm', 'Tập 21 của bộ manga "Thanh gươm diệt quỷ" của Koyoharu Gotouge. Trận chiến với Thượng Huyền tiếp diễn, đồng thời những ký ức xa xưa về hơi thở đầu tiên dần được hé lộ.'],
            51 => [334, '22 x 14 x 1.6 cm', 'Tiểu thuyết của nhà văn Chu Lai về 81 ngày đêm chiến đấu bảo vệ Thành cổ Quảng Trị năm 1972. Tác phẩm khắc họa sự hy sinh của những người lính trẻ và nỗi đau chiến tranh qua những trang viết chân thực, xúc động.'],
            52 => [272, '20.5 x 14.5 x 1.3 cm', 'Tiểu thuyết tình cảm của Tuế Kiến về một mối tình nhiều tiếc nuối và những giấc mơ còn dang dở. Câu chuyện nhẹ nhàng nhưng day dứt, dành cho những ai yêu thích dòng văn học lãng mạn.'],
            53 => [227, '20.5 x 13 cm', 'Tác phẩm nổi tiếng của Paulo Coelho kể về chàng chăn cừu Santiago rời quê hương đi tìm kho báu theo một giấc mơ. Trên hành trình, cậu học được cách lắng nghe trái tim và theo đuổi vận mệnh của chính mình.'],
            54 => [284, '20.5 x 13 x 1.3 cm', 'Tiểu thuyết tình cảm của Thương Thái Vi về một tình yêu thầm lặng, đầy hy sinh. Câu chuyện cảm động về sự chờ đợi, mất mát và cách người ta yêu thương nhau trọn vẹn.'],
            55 => [263, '20.5 x 13 x 1.2 cm', 'Tập tản văn của Phạm Lữ Ân viết cho người trẻ về tuổi trẻ, gia đình, tình yêu và giá trị của thời gian. Ấn bản kỷ niệm 10 năm nhắc người đọc sống chậm lại và trân trọng những điều quan trọng khi đời người là hữu hạn.'],
            56 => [260, '24 x 16 x 1.3 cm', 'Tập hợp các bài giảng của "Giáo Tiến" Hoàng Nam Tiến về trí tuệ nhân tạo và cách doanh nghiệp ứng dụng AI. Sách giúp nhà quản lý hiểu vì sao AI là nhân tố thay đổi cuộc chơi và cách bắt đầu chuyển đổi trong kỷ nguyên mới.'],
            57 => [444, '19 x 13 x 2.4 cm', 'Tiểu thuyết của nhà văn Sơn Tùng kể về thời niên thiếu và tuổi trẻ của Chủ tịch Hồ Chí Minh, từ làng Sen quê nhà đến khi ra đi tìm đường cứu nước. Ấn bản bìa cứng phát hành nhân kỷ niệm 135 năm ngày sinh của Bác, kèm obi và postcard.'],
            58 => [400, '20.5 x 13.5 cm', 'Tiểu thuyết của Phùng Quán về những thiếu niên trinh sát của Trung đoàn Thủ Đô trong kháng chiến chống Pháp. Tập 1 mở đầu câu chuyện về Mừng, Quỳnh sơn ca và các đồng đội nhỏ tuổi với một tuổi thơ dữ dội, đầy lý tưởng và hy sinh.'],
        ];

        foreach ($details as $id => [$pageCount, $dimensions, $description]) {
            DB::table('books')->where('id', $id)->update([
                'page_count' => $pageCount,
                'dimensions' => $dimensions,
                'description' => $description,
            ]);
        }

